#!/usr/bin/env python3
"""Pack four canonical NVIDIA STBN scalar components into a C++ byte array.

Source archive: NVIDIA-RTX/STBN Assets/STBN.zip
Pinned repository: 48b2839e4d8b7f0202ac72c6b0ae720d235a5b8b
"""

import pathlib
import struct
import sys

WIDTH = 128
HEIGHT = 128
DEPTH = 64


def read_png(path: pathlib.Path):
	data = path.read_bytes()
	assert data[:8] == b"\x89PNG\r\n\x1a\n"
	pos = 8
	compressed = bytearray()
	width = height = bit_depth = color_type = None
	while pos < len(data):
		length = struct.unpack(">I", data[pos:pos + 4])[0]
		kind = data[pos + 4:pos + 8]
		payload = data[pos + 8:pos + 8 + length]
		pos += 12 + length
		if kind == b"IHDR":
			width, height, bit_depth, color_type, _, _, _ = struct.unpack(">IIBBBBB", payload)
		elif kind == b"IDAT":
			compressed += payload
		elif kind == b"IEND":
			break
	assert (width, height, bit_depth) == (WIDTH, HEIGHT, 8)
	channels = {0: 1, 6: 4}[color_type]
	import zlib
	raw = zlib.decompress(compressed)
	stride = width * channels
	rows = []
	previous = bytearray(stride)
	index = 0
	for _ in range(height):
		filter_type = raw[index]
		index += 1
		row = bytearray(raw[index:index + stride])
		index += stride
		for x in range(stride):
			left = row[x - channels] if x >= channels else 0
			up = previous[x]
			up_left = previous[x - channels] if x >= channels else 0
			if filter_type == 1:
				row[x] = (row[x] + left) & 255
			elif filter_type == 2:
				row[x] = (row[x] + up) & 255
			elif filter_type == 3:
				row[x] = (row[x] + ((left + up) // 2)) & 255
			elif filter_type == 4:
				p = left + up - up_left
				pa, pb, pc = abs(p - left), abs(p - up), abs(p - up_left)
				row[x] = (row[x] + (left if pa <= pb and pa <= pc else up if pb <= pc else up_left)) & 255
			elif filter_type != 0:
				raise ValueError(f"unsupported PNG filter {filter_type}")
		rows.append(row)
		previous = row
	return [[row[x * channels] for x in range(width)] for row in rows] if channels == 1 else [[row[x * channels:x * channels + channels] for x in range(width)] for row in rows]


def main(source: pathlib.Path, output: pathlib.Path):
	root = source / "STBN"
	stems = [
		("stbn_scalar_2Dx1Dx1D_128x128x64x1", 0),
		("stbn_vec1_2Dx1D_128x128x64", 0),
		("stbn_vec2_2Dx1D_128x128x64", 0),
		("stbn_vec2_2Dx1D_128x128x64", 1),
	]
	packed = bytearray()
	for depth in range(DEPTH):
		planes = []
		for stem, component in stems:
			image = read_png(root / f"{stem}_{depth}.png")
			planes.append([[pixel if isinstance(pixel, int) else pixel[component] for pixel in row] for row in image])
		for y in range(HEIGHT):
			for x in range(WIDTH):
				packed.extend((planes[0][y][x], planes[1][y][x], planes[2][y][x], planes[3][y][x]))
	with output.open("w", encoding="ascii") as stream:
		stream.write("// Generated by generate_packed_stbn.py; do not edit.\n")
		stream.write("#pragma once\n#include <cstdint>\n\n")
		stream.write(f"static constexpr uint32_t FLUX_STBN_PACKED_DATA_SIZE = {len(packed)}u;\n")
		stream.write("alignas(16) static const uint8_t FLUX_STBN_PACKED_DATA[] = {\n")
		for start in range(0, len(packed), 16):
			stream.write("\t" + ", ".join(f"0x{value:02x}" for value in packed[start:start + 16]) + ",\n")
		stream.write("};\n")


if __name__ == "__main__":
	if len(sys.argv) != 3:
		raise SystemExit("usage: generate_packed_stbn.py <extracted-STBN-root> <output-header>")
	main(pathlib.Path(sys.argv[1]), pathlib.Path(sys.argv[2]))
